//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_extract_fast`; the
//! native twin is `benches/native/Bench/StringUtf8ExtractFast.lean`.
//! the bytes copied into a new buffer, as Lean makes a new string

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::string;
use lean_runtime_bench::{mixed, run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(String, Vec<u64>), n: u64) -> u64 {
    let (s, ps) = (inp.0.as_bytes(), &inp.1);
    let np = ps.len() as u64;
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(
            s[string::utf8_extract_fast(s, ps[(x % np) as usize], ps[((x >> 32) % np) as usize])]
                .to_vec()
                .len() as u64,
        );
    }
    acc as u64
}

fn main() {
    run(
        || {
            let s = mixed();
            let mut ps: Vec<u64> = s.char_indices().map(|(i, _)| i as u64).collect();
            ps.push(s.len() as u64);
            (s, ps)
        },
        kernel,
    )
}
